-- Generated by build.py from assessments/*.json. Run schema.sql first. Safe to run again: it replaces the questions.

insert into public.assessments (slug, title, pass_pct, questions) values ('as-comparative-advantage', $q$Comparative Advantage: assessment$q$, 80, $q$[{"id": "q1", "type": "num", "q": "Blue can make at most 40 coats or 160 shirts. How many shirts does Blue give up to make 1 coat?", "ans": 4, "tol": 0, "marks": 1, "topic": "Opportunity cost", "hint": "Enter a number.", "ok": "Correct: 160 ÷ 40 = 4 shirts.", "fb": "Divide what is given up (shirts) by what is gained (coats): 160 ÷ 40 = 4. Revisit Step 2 of the worked example in the Learn tab.", "model": "4"}, {"id": "q2", "type": "num", "q": "Red can make at most 120 coats or 240 shirts. How many coats does Red give up to make 1 shirt? (give a decimal)", "ans": 0.5, "tol": 0.01, "marks": 1, "topic": "Opportunity cost", "hint": "Enter a number.", "ok": "Correct: 120 ÷ 240 = 0.5 coat.", "fb": "The opportunity cost of a shirt is the inverse of the coat calculation: coats given up ÷ shirts gained = 120 ÷ 240 = 0.5. Check Step 2 again.", "model": "0.5"}, {"id": "q3", "type": "mcq", "q": "Using the figures above, which country has the comparative advantage in coats?", "opts": ["Red", "Blue", "Both countries", "Neither country"], "ans": "0", "marks": 1, "topic": "Comparative advantage", "ok": "Correct: Red gives up 2 shirts per coat, Blue gives up 4, so Red's opportunity cost is lower.", "fb": "Compare opportunity costs, not total output. Red gives up 2 shirts per coat and Blue gives up 4, so Red is the lower-cost producer of coats. Re-read the table in Step 2.", "model": "Red"}, {"id": "q4", "type": "text", "q": "Define comparative advantage.", "groups": [["opportunity cost"], ["lower", "less", "fewer", "smaller", "lowest"]], "marks": 2, "topic": "Definitions", "ok": "Full marks: you linked it to opportunity cost and to being lower.", "fb": "Two ideas are needed: it is about opportunity cost, and the country with the lower opportunity cost holds the advantage. Learn the wording in the Tips & keywords tab.", "model": "A country has a comparative advantage in a good if it can produce it at a lower opportunity cost than another country, meaning it gives up fewer other goods to make it.", "hint": "One sentence."}, {"id": "q5", "type": "text", "q": "A country can make every good using fewer resources than its trading partner. Could it still gain from trade? Answer yes or no and explain briefly.", "groups": [["yes", "could", "may"], ["comparative", "opportunity cost", "specialis*", "lower cost"]], "marks": 2, "topic": "Absolute vs comparative", "ok": "Full marks: the gain comes from comparative, not absolute, advantage.", "fb": "Absolute advantage in everything does not stop trade being worthwhile. The gain comes from specialising where the opportunity cost is lower. Re-read 'A country can have an absolute advantage in everything and still gain from trade' in the Learn tab.", "model": "Yes. Even with an absolute advantage in everything, the country is likely to have a lower opportunity cost in some goods. If it specialises in those and trades, both countries could consume more than they could alone."}, {"id": "q6", "type": "mcq", "q": "In the worked example a coat costs Red 2 shirts and Blue 4 shirts to make. Between which rates of exchange could both countries gain?", "opts": ["Under 2 shirts per coat", "Between 2 and 4 shirts per coat", "Over 4 shirts per coat", "Exactly 3 shirts per coat only"], "ans": "1", "marks": 1, "topic": "Terms of trade", "ok": "Correct: Red wants more than 2 shirts per coat, Blue will pay less than 4.", "fb": "Each side must receive a better deal than making the good itself. Red will not sell a coat for under 2 shirts, and Blue will not pay more than 4. Revisit Step 5.", "model": "Between 2 and 4 shirts per coat"}, {"id": "q7", "type": "num", "q": "Red makes only coats (120) and Blue makes only shirts (160). How many shirts does the world produce?", "ans": 160, "tol": 0, "marks": 1, "topic": "Specialisation", "hint": "Enter a number.", "ok": "Correct: only Blue makes shirts, so the world total is 160.", "fb": "After specialising, only Blue makes shirts, so world shirt output is Blue's maximum of 160. See Step 4.", "model": "160"}, {"id": "q8", "type": "num", "q": "At an exchange rate of 3 shirts per coat, Red sells 40 coats. How many shirts does Red receive?", "ans": 120, "tol": 0, "marks": 1, "topic": "Terms of trade", "hint": "Enter a number.", "ok": "Correct: 40 × 3 = 120 shirts.", "fb": "Shirts received = coats sold × shirts per coat = 40 × 3 = 120. See Step 6.", "model": "120"}, {"id": "q9", "type": "text", "q": "Name two limitations or risks of a country specialising heavily according to comparative advantage.", "groups": [["overspecialis*", "over-specialis*", "over reliance", "overreliance", "over-reliance", "too reliant", "dependen*", "depend on", "relies on", "rely on"], ["unemploy*", "structural"], ["transport", "freight", "shipping"], ["tariff*", "protection*", "quota*", "trade barrier*"], ["decline", "falling demand", "price fall*", "volatil*", "fluctuat*", "shock*", "commodity prices"], ["non-renewable", "run out", "exhaust*", "depleted"], ["diseconom*"]], "marks": 2, "topic": "Limitations", "ok": "Full marks: two different limitations.", "fb": "Pick two distinct points, such as over-dependence on a few exports, structural unemployment when an industry declines, or transport costs. A weak answer repeats one point twice. See the Exam questions tab.", "model": "Two examples: the country could become over-dependent on a few exports, so a fall in world prices may hurt it badly; and workers in industries that decline after specialising may become structurally unemployed.", "hint": "Give two different points."}, {"id": "q10", "type": "text", "q": "What name is given to the rate at which one country's goods exchange for another's?", "groups": [["terms of trade"]], "marks": 1, "topic": "Terms of trade", "ok": "Correct.", "fb": "The term is 'terms of trade'. Add it to your keyword list in the Tips & keywords tab.", "model": "The terms of trade."}]$q$::jsonb)
on conflict (slug) do update set title = excluded.title, pass_pct = excluded.pass_pct, questions = excluded.questions, updated_at = now();

insert into public.assessments (slug, title, pass_pct, questions) values ('as-elasticities-of-demand', $q$Elasticities of Demand: assessment$q$, 80, $q$[{"id": "q1", "type": "num", "q": "Price rises from $10 to $12 and quantity demanded falls from 1,000 to 900. Calculate PED (ignore the sign, give one decimal).", "ans": 0.5, "tol": 0.05, "marks": 1, "topic": "PED calculation", "hint": "Enter a number.", "ok": "Correct: %ΔP = 20%, %ΔQ = 10%, PED = 10 ÷ 20 = 0.5.", "fb": "Use percentage changes on the original value: %ΔP = 2 ÷ 10 = 20%, %ΔQ = 100 ÷ 1,000 = 10%. PED = 10 ÷ 20 = 0.5. Revisit the PED formula in the Learn tab.", "model": "0.5", "abs": true}, {"id": "q2", "type": "num", "q": "Incomes rise by 5% and demand for a good rises by 15%. Calculate YED.", "ans": 3, "tol": 0.01, "marks": 1, "topic": "YED calculation", "hint": "Enter a number.", "ok": "Correct: 15 ÷ 5 = 3.", "fb": "YED = %ΔQd ÷ %ΔY = 15 ÷ 5 = 3. A figure above 1 suggests a luxury or income-elastic good.", "model": "3"}, {"id": "q3", "type": "num", "q": "The price of good B rises by 10% and demand for good A falls by 25%. Calculate XED, including the sign.", "ans": -2.5, "tol": 0.05, "marks": 1, "topic": "XED calculation", "hint": "Include the minus sign if it is negative.", "ok": "Correct: −25 ÷ 10 = −2.5, which suggests complements.", "fb": "XED = %ΔQd of A ÷ %ΔP of B = −25 ÷ 10 = −2.5. Keep the sign for XED, because it shows whether the goods are substitutes or complements.", "model": "-2.5"}, {"id": "q4", "type": "mcq", "q": "A good has a PED of 0.4. If its price rises, what is likely to happen to total revenue?", "opts": ["It rises", "It falls", "It stays the same", "It cannot be known"], "ans": "0", "marks": 1, "topic": "PED and revenue", "ok": "Correct: demand is inelastic, so quantity falls proportionally less than price rises.", "fb": "With PED below 1 (inelastic), the % fall in quantity is smaller than the % rise in price, so revenue tends to rise. See the revenue table in the Learn tab.", "model": "It rises"}, {"id": "q5", "type": "mcq", "q": "A firm cuts the price of a product with PED = 1.8. What is likely to happen to its revenue?", "opts": ["It rises", "It falls", "No change", "It depends on costs"], "ans": "0", "marks": 1, "topic": "PED and revenue", "ok": "Correct: elastic demand means a price cut tends to raise revenue.", "fb": "PED above 1 (elastic): the % rise in quantity is bigger than the % fall in price, so revenue tends to rise. See Lab 1 in the Explore tab.", "model": "It rises"}, {"id": "q6", "type": "mcq", "q": "A negative YED indicates which type of good?", "opts": ["Luxury good", "Normal necessity", "Inferior good", "Complement"], "ans": "2", "marks": 1, "topic": "YED", "ok": "Correct.", "fb": "A negative income elasticity means demand falls as income rises, which is the definition of an inferior good. Examples include own-brand value ranges.", "model": "Inferior good"}, {"id": "q7", "type": "text", "q": "Define price elasticity of demand.", "groups": [["responsive*", "sensitiv*", "extent", "how much", "degree"], ["own price", "change in price", "price change", "change in the price", "price of the product", "price of a product", "price of the good", "a change in price", "to price", "to the price", "to its price", "changes in price", "price changes", "change in its price"]], "marks": 2, "topic": "Definitions", "ok": "Full marks: responsiveness of quantity demanded to a change in price.", "fb": "Two parts: it measures the responsiveness (how much) of quantity demanded, to a change in the good's own price. Revisit 'Three elasticities of demand' in the Learn tab.", "model": "PED measures the responsiveness of quantity demanded of a product to a change in its own price, ceteris paribus.", "hint": "One sentence."}, {"id": "q8", "type": "text", "q": "State three factors that could affect the price elasticity of demand for a product.", "groups": [["substitut*"], ["proportion of income", "share of income", "relative expense", "expensive", "percentage of income"], ["time", "long run", "short run"], ["necessit*", "luxur*"], ["addict*", "habit*"], ["brand loyal*", "loyal*", "brand"]], "marks": 3, "topic": "Determinants", "ok": "Full marks: three different determinants.", "fb": "Three different determinants are needed, such as availability of substitutes, relative expense, time period, necessity or luxury, addiction and brand loyalty. See 'What determines PED?' in the Learn tab.", "model": "Availability and closeness of substitutes (more substitutes tends to make demand more elastic); the proportion of income spent on it (larger share, more elastic); and the time period (longer run, more elastic).", "hint": "Three short points."}, {"id": "q9", "type": "text", "q": "The XED between butter and margarine is +1.8. What type of relationship does this show?", "groups": [["substitut*"]], "marks": 1, "topic": "XED", "ok": "Correct: a positive XED suggests substitutes.", "fb": "A positive XED means that when the price of one good rises, demand for the other rises too, which is how substitutes behave. Negative would suggest complements.", "model": "Substitutes."}, {"id": "q10", "type": "mcq", "q": "Along a straight-line demand curve, where is demand most price elastic?", "opts": ["At a high price, low quantity", "At the midpoint", "At a low price, high quantity", "PED is the same everywhere"], "ans": "0", "marks": 1, "topic": "PED along a curve", "ok": "Correct: at high prices, small absolute changes are large percentage changes.", "fb": "The slope is constant but PED is not, because it uses percentages. At the top left a small change in quantity is a large percentage change, so demand is more elastic. Watch the animation in the Watch tab.", "model": "At a high price, low quantity"}]$q$::jsonb)
on conflict (slug) do update set title = excluded.title, pass_pct = excluded.pass_pct, questions = excluded.questions, updated_at = now();

insert into public.assessments (slug, title, pass_pct, questions) values ('linked-lists', $q$Linked Lists: assessment$q$, 80, $q$[{"id": "q1", "type": "mcq", "q": "What value is normally used as the null pointer at the end of a linked list?", "opts": ["0", "1", "-1", "The length of the list"], "ans": "2", "marks": 1, "topic": "Null pointer", "ok": "Correct: the last node's pointer is -1.", "fb": "The end of the list is marked by a null pointer, which the course uses as -1. Revisit section 01 (The idea).", "model": "-1"}, {"id": "q2", "type": "text", "q": "State what the heapStartPointer holds.", "groups": [["first free", "free slot", "free space", "unused", "next free", "empty"]], "marks": 1, "topic": "The heap", "ok": "Correct: it points at the first free slot.", "fb": "heapStartPointer holds the index of the first free (unused) slot, because the unused positions are themselves kept as a linked list. See section 02 (Anatomy).", "model": "The index of the first free (unused) position in the arrays.", "hint": "One short phrase."}, {"id": "q3", "type": "mcq", "q": "In the array implementation, how many arrays hold the list?", "opts": ["One 2D array", "Two parallel 1D arrays", "Three arrays", "A real memory address list"], "ans": "1", "marks": 1, "topic": "Anatomy", "ok": "Correct: one array for data, one for pointers.", "fb": "Exam questions use two parallel 1D arrays of the same size: one for data, one for the next-pointers. They do not use real memory addresses. See section 02.", "model": "Two parallel 1D arrays"}, {"id": "q4", "type": "num", "q": "Data array: [27, 19, 36, 42, 16] at indexes 0 to 4. Pointer array: [2, 0, 3, -1, 1]. startPointer = 4. What is the third item in the list order? (follow the pointers from startPointer)", "ans": 27, "tol": 0, "marks": 1, "topic": "Tracing", "hint": "Enter a number.", "ok": "Correct: 16, then 19, then 27.", "fb": "Start at index 4 (16), its pointer is 1 so go to index 1 (19), whose pointer is 0, so index 0 (27). The third item is 27. Practise the trace tables in section 03.", "model": "27"}, {"id": "q5", "type": "num", "q": "Using the same arrays, at which array index is the item 36 stored?", "ans": 2, "tol": 0, "marks": 1, "topic": "Anatomy", "hint": "Enter a number.", "ok": "Correct: index 2.", "fb": "The data array is [27, 19, 36, 42, 16], so 36 is at index 2. The index where an item is stored is not its position in the list order.", "model": "2"}, {"id": "q6", "type": "mcq", "q": "The find function starts its search at which index?", "opts": ["Index 0", "The index in startPointer", "The last index", "heapStartPointer"], "ans": "1", "marks": 1, "topic": "Finding", "ok": "Correct.", "fb": "You do not scan from index 0. Start at startPointer and follow the chain of pointers. See section 03.", "model": "The index in startPointer"}, {"id": "q7", "type": "text", "q": "What does the find function return if the item is not in the list?", "groups": [["-1", "minus 1", "null pointer", "nullpointer", "null"]], "marks": 1, "topic": "Finding", "ok": "Correct.", "fb": "The loop stops when itemPointer reaches the null pointer, so the function returns -1. See section 03.", "model": "-1 (the null pointer).", "hint": "A value."}, {"id": "q8", "type": "mcq", "q": "When inserting a new node into the middle of a sorted linked list, which of these is NOT needed?", "opts": ["Moving existing data items along the array", "Taking a free slot from the heap", "Changing the previous node's pointer", "Giving the new node a pointer to the next node"], "ans": "0", "marks": 1, "topic": "Inserting", "ok": "Correct: no data ever moves.", "fb": "The point of a linked list is that no data moves. You take a free slot, set the new node's pointer and redirect the previous node's pointer. See section 04.", "model": "Moving existing data items along the array"}, {"id": "q9", "type": "text", "q": "Explain one advantage of a linked list over a sorted array when inserting an item.", "groups": [["no need to shift", "not shift*", "without shifting", "no data moves", "not move*", "avoid* mov*", "avoid* shift*", "don't need to move", "do not need to move", "only pointers", "pointers change", "change pointers", "only two pointers", "not have to move", "not have to shift", "don t need to move", "don t need to shift", "no need to move", "not need to move", "not need to shift", "does not need to move", "doesn t need to move", "doesn t have to"]], "marks": 1, "topic": "Linked list vs array", "ok": "Correct.", "fb": "The key idea is that existing items do not need to be shifted along; only pointers are changed. See section 06 (vs. arrays).", "model": "Items do not have to be shifted along to make room, because only a couple of pointers need to change, which may make insertion quicker for large lists.", "hint": "One sentence."}, {"id": "q10", "type": "num", "q": "A linked list is made from arrays of 12 elements and currently holds 5 items. How many nodes are on the heap?", "ans": 7, "tol": 0, "marks": 1, "topic": "The heap", "hint": "Enter a number.", "ok": "Correct: 12 − 5 = 7.", "fb": "Every position not in the list is on the heap (the free list). 12 − 5 = 7. See section 02.", "model": "7"}]$q$::jsonb)
on conflict (slug) do update set title = excluded.title, pass_pct = excluded.pass_pct, questions = excluded.questions, updated_at = now();
